import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Bumper cars (dodgems) modelled from the RCT2 sprite: a fenced arena with a
// powered ceiling grid and four rounded cars darting about, each with a driver.
export function BumperCars() {
  return (
    <Stage
      distance={6.5}
      targetY={0.8}
      build={(t, g) => {
        const A = 2.4;
        g.add(box(t, [A + 0.4, 0.15, A + 0.4], 0x3a3f48, [0, 0.07, 0], { tex: 'metal', repeat: [8, 8], metal: 0.5, rough: 0.5 }));
        // low walls
        [-1, 1].forEach((s) => {
          g.add(box(t, [A + 0.4, 0.4, 0.12], 0xd23a4a, [0, 0.3, (s * (A + 0.4)) / 2], { tex: 'plastic', repeat: [8, 1], rough: 0.5 }));
          g.add(box(t, [0.12, 0.4, A + 0.4], 0xe0e0e0, [(s * (A + 0.4)) / 2, 0.3, 0], { tex: 'plastic', repeat: [8, 1], rough: 0.5 }));
        });
        // ceiling grid + posts
        [-1, 1].forEach((sx) => [-1, 1].forEach((sz) => g.add(cyl(t, 0.05, 0.05, 1.9, 0x2b2b30, [(sx * A) / 2, 1.0, (sz * A) / 2], { tex: 'metal', metal: 0.6, rough: 0.4, seg: 8 }))));
        g.add(box(t, [A, 0.06, A], 0x23242a, [0, 1.95, 0], { tex: 'metal', repeat: [10, 10], metal: 0.6, rough: 0.5, opacity: 0.9 }));
        for (let i = -2; i <= 2; i++) g.add(box(t, [A, 0.02, 0.03], 0x33343a, [0, 1.9, (i * A) / 5], { metal: 0.5 }));

        const BODY = 0x2e4444; // dark teal body (sprite #305050)
        const skirts = [0xe8641c, 0xd6338c, 0xe8641c, 0xd23a4a]; // orange/pink bumper rings
        const cars = [];
        for (let i = 0; i < 4; i++) {
          const car = new t.Group();
          car.add(cyl(t, 0.36, 0.4, 0.16, skirts[i], [0, 0.1, 0], { rough: 0.55, seg: 20 })); // round bumper skirt
          car.add(cyl(t, 0.41, 0.41, 0.05, 0x111116, [0, 0.04, 0], { rough: 0.7, seg: 20 })); // rubber ring
          car.add(box(t, [0.36, 0.24, 0.46], BODY, [0, 0.28, -0.02], { tex: 'plastic', repeat: [2, 1], rough: 0.45 })); // teal body
          car.add(box(t, [0.38, 0.05, 0.48], skirts[i], [0, 0.18, -0.02], { rough: 0.5 })); // trim line
          car.add(box(t, [0.34, 0.12, 0.2], 0x111116, [0, 0.36, 0.18], { rough: 0.7 })); // dash
          car.add(cyl(t, 0.02, 0.02, 1.6, 0x777, [0, 1.1, -0.15], { metal: 0.6, rough: 0.4, seg: 6 })); // pole
          car.add(ball(t, 0.05, 0x66e0ff, [0, 1.9, -0.15], { emissive: 0x2288aa })); // contact
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i], seated: true });
          p.group.scale.setScalar(0.42);
          p.group.position.set(0, 0.16, -0.02);
          car.add(p.group);
          g.add(car);
          cars.push(car);
        }
        const lim = A / 2 - 0.4;
        return (time) => {
          cars.forEach((c, i) => {
            const t2 = time * (0.8 + i * 0.15) + i * 1.7;
            const x = Math.sin(t2 * 1.1) * lim;
            const z = Math.cos(t2 * 0.9 + i) * lim;
            const nx = Math.cos(t2 * 1.1) * 1.1 * lim;
            const nz = -Math.sin(t2 * 0.9 + i) * 0.9 * lim;
            c.position.set(x, 0.1, z);
            c.rotation.y = Math.atan2(nx, nz);
          });
        };
      }}
    />
  );
}

import React from 'react';
import * as THREE from 'three';
import { Stage, box, cyl } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Go-karts modelled from the RCT2 track ride: an oval asphalt circuit with red
// kerbs and four karts (with drivers) racing around it.
export function GoKarts() {
  return (
    <Stage
      distance={7.5}
      targetY={0.5}
      build={(t, g) => {
        const R = 2.2;
        const track = new t.Mesh(new t.TorusGeometry(R, 0.62, 12, 60), new t.MeshStandardMaterial({ color: 0x3a3d42, roughness: 0.96 }));
        track.rotation.x = -Math.PI / 2;
        track.position.y = 0.06;
        track.receiveShadow = true;
        g.add(track);
        [R - 0.6, R + 0.6].forEach((rr) => {
          const k = new t.Mesh(new t.TorusGeometry(rr, 0.05, 8, 60), new t.MeshStandardMaterial({ color: 0xdd3838, roughness: 0.6 }));
          k.rotation.x = -Math.PI / 2;
          k.position.y = 0.14;
          g.add(k);
        });
        const cols = [0xe8641c, 0xf08a30, 0xe8641c, 0xd6541a]; // orange fleet like KART1
        const karts: THREE.Group[] = [];
        for (let i = 0; i < 4; i++) {
          const k = new t.Group();
          k.add(box(t, [0.32, 0.14, 0.62], 0x141417, [0, 0.14, 0], { tex: 'metal', metal: 0.5, rough: 0.5 }));
          k.add(box(t, [0.34, 0.16, 0.4], cols[i], [0, 0.26, -0.04], { tex: 'plastic', repeat: [1, 1], rough: 0.35 }));
          k.add(box(t, [0.22, 0.14, 0.22], 0x101014, [0, 0.32, -0.16], { rough: 0.8 }));
          k.add(cyl(t, 0.09, 0.09, 0.34, 0x0a0a0d, [0, 0.3, 0.28], { rotZ: Math.PI / 2, seg: 8, rough: 0.7 })); // steering column base
          [[-0.18, 0.22], [0.18, 0.22], [-0.18, -0.22], [0.18, -0.22]].forEach(([x, z]) =>
            k.add(cyl(t, 0.09, 0.09, 0.08, 0x141417, [x, 0.09, z], { rotZ: Math.PI / 2, seg: 12, tex: 'metal', metal: 0.4, rough: 0.5 })),
          );
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[i], seated: true });
          p.group.scale.setScalar(0.36);
          p.group.position.set(0, 0.16, -0.05);
          k.add(p.group);
          k.add(cyl(t, 0.085, 0.085, 0.1, 0xf0f0f4, [0, 0.52, -0.05], { rough: 0.35, seg: 14 })); // white helmet
          g.add(k);
          karts.push(k);
        }
        return (time) => {
          karts.forEach((k, i) => {
            const a = time * 0.7 + (i / 4) * Math.PI * 2;
            k.position.set(Math.cos(a) * R, 0.1, Math.sin(a) * R);
            k.rotation.y = -a + Math.PI / 2;
          });
        };
      }}
    />
  );
}

import React from 'react';
import { Stage, box, cyl, ball } from '../Stage';
import { buildPeep, SHIRTS, SKIN_TONES } from '../Guest';

// Log flume modelled from the RCT2 water ride: an elevated wooden trough of
// blue water on posts, with a hollow log boat of riders sliding along it.
export function LogFlume() {
  return (
    <Stage
      distance={7.5}
      targetY={0.9}
      background="#bfe6f2"
      build={(t, g) => {
        const RUN = 6.4;
        g.add(box(t, [1.0, 0.16, RUN], 0x5a3d22, [0, 0.6, 0], { tex: 'wood', repeat: [4, 22], rough: 0.8 }));
        [-0.5, 0.5].forEach((x) => g.add(box(t, [0.1, 0.34, RUN], 0x4a3018, [x, 0.76, 0], { tex: 'wood', repeat: [1, 22], rough: 0.8 })));
        g.add(box(t, [0.84, 0.06, RUN], 0x2a8fd0, [0, 0.74, 0], { emissive: 0x115f9c, rough: 0.2, opacity: 0.9 })); // water
        for (let z = -RUN / 2 + 0.5; z < RUN / 2; z += 1.4)
          [-0.5, 0.5].forEach((x) => g.add(cyl(t, 0.08, 0.09, 0.7, 0x5a3d22, [x, 0.25, z], { tex: 'wood', repeat: [1, 1], rough: 1, seg: 8 })));

        const boat = new t.Group();
        g.add(boat);
        boat.add(cyl(t, 0.3, 0.3, 1.2, 0x8a5a28, [0, 0, 0], { rotX: Math.PI / 2, tex: 'wood', repeat: [6, 2], rough: 0.9, seg: 18 })); // bark barrel (along z)
        boat.add(ball(t, 0.3, 0x8a5a28, [0, 0, 0.6], { tex: 'wood', repeat: [3, 3], flat: true, rough: 0.9 })); // rounded nose
        boat.add(ball(t, 0.3, 0x8a5a28, [0, 0, -0.6], { tex: 'wood', repeat: [3, 3], flat: true, rough: 0.9 })); // rounded tail
        boat.add(box(t, [0.5, 0.06, 1.24], 0xe8cc80, [0, 0.16, 0], { rough: 0.7 })); // cream cut rim
        boat.add(box(t, [0.4, 0.18, 1.1], 0x2a1c10, [0, 0.12, 0], { rough: 0.9 })); // hollowed interior
        for (let i = 0; i < 3; i++) {
          const p = buildPeep(t, { skin: SKIN_TONES[i % SKIN_TONES.length], shirt: SHIRTS[(i + 3) % SHIRTS.length], seated: true, expression: i === 0 ? 'surprised' : 'happy' });
          p.group.scale.setScalar(0.42);
          p.group.position.set(0, 0.12, -0.42 + i * 0.42);
          boat.add(p.group);
        }
        return (time) => {
          const z = ((time * 1.4) % (RUN + 1.5)) - (RUN / 2 + 0.75);
          boat.position.set(0, 0.86, z);
        };
      }}
    />
  );
}

import React from 'react';
import { Stage, box, cyl } from '../Stage';
import { buildPeep } from '../Guest';

// Bobsleigh car modelled from the RCT2 vehicle sprite: a sleek two-seat pod on
// chrome runners inside a banked half-pipe chute.
export function BobsleighCar() {
  return (
    <Stage
      distance={4.6}
      targetY={0.5}
      build={(t, g) => {
        g.add(box(t, [1.5, 0.12, 3], 0x9fb0c0, [0, 0.06, 0], { tex: 'concrete', repeat: [3, 10], rough: 0.9 }));
        [-0.75, 0.75].forEach((x) => g.add(box(t, [0.12, 0.55, 3], 0xbcc6d2, [x, 0.28, 0], { tex: 'concrete', repeat: [1, 10], rough: 0.9, rotZ: x > 0 ? -0.22 : 0.22 })));
        const sled = new t.Group();
        sled.position.y = 0.22;
        g.add(sled);
        sled.add(box(t, [0.42, 0.24, 1.25], 0xe8641c, [0, 0.17, 0], { tex: 'plastic', repeat: [1, 3], rough: 0.3 }));
        sled.add(box(t, [0.46, 0.1, 1.3], 0xc44a14, [0, 0.06, 0], { tex: 'plastic', rough: 0.3 }));
        sled.add(box(t, [0.3, 0.22, 0.55], 0x2e2e34, [0, 0.26, -0.12], { rough: 0.85 }));
        sled.add(box(t, [0.44, 0.18, 0.4], 0xf0b030, [0, 0.2, 0.5], { rotX: -0.4, tex: 'plastic', rough: 0.3 })); // gold nose cowl
        sled.add(box(t, [0.46, 0.05, 1.1], 0xd6338c, [0, 0.26, -0.05], { rough: 0.45 })); // pink rim stripe // nose cowl
        [-0.19, 0.19].forEach((x) => sled.add(box(t, [0.04, 0.05, 1.34], 0xd0d4da, [x, -0.02, 0], { tex: 'metal', metal: 0.85, rough: 0.2 })));
        [0.28, -0.22].forEach((z, i) => {
          const p = buildPeep(t, { shirt: [0xd6338c, 0xf0b030][i], seated: true, expression: 'surprised' });
          p.group.scale.setScalar(0.4);
          p.group.position.set(0, 0.14, z);
          sled.add(p.group);
        });
        return (time) => {
          sled.position.y = 0.22 + Math.sin(time * 2) * 0.01;
          sled.rotation.z = Math.sin(time * 1.5) * 0.06;
        };
      }}
    />
  );
}
